static std::string PatchUtf8V11(const std::wstring& value){if(value.empty())return {};int needed=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,value.data(),(int)value.size(),nullptr,0,nullptr,nullptr);if(needed<=0)throw 1;std::string out((size_t)needed,'\0');if(WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,value.data(),(int)value.size(),out.data(),needed,nullptr,nullptr)!=needed)throw 1;return out;}

static bool ReadSelfPayloadV11(std::vector<uint8_t>& payload){wchar_t path[MAX_PATH];DWORD n=GetModuleFileNameW(nullptr,path,MAX_PATH);if(!n||n>=MAX_PATH)return false;HANDLE file=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER size{};if(!GetFileSizeEx(file,&size)||size.QuadPart<20){CloseHandle(file);return false;}LARGE_INTEGER pos{};pos.QuadPart=size.QuadPart-20;if(!SetFilePointerEx(file,pos,nullptr,FILE_BEGIN)){CloseHandle(file);return false;}uint8_t footer[20]{};DWORD got=0;if(!ReadFile(file,footer,20,&got,nullptr)||got!=20||memcmp(footer,PATCH_MAGIC,8)!=0){CloseHandle(file);return false;}auto le32=[](const uint8_t*p){return(uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);};const uint32_t version=le32(footer+8),length=le32(footer+12),crc=le32(footer+16);if(version!=10||!length||(uint64_t)length>(uint64_t)(size.QuadPart-20)){CloseHandle(file);return false;}pos.QuadPart=size.QuadPart-20-length;if(!SetFilePointerEx(file,pos,nullptr,FILE_BEGIN)){CloseHandle(file);return false;}payload.resize(length);got=0;BOOL ok=ReadFile(file,payload.data(),length,&got,nullptr);CloseHandle(file);return ok&&got==length&&Crc32(payload.data(),payload.size())==crc;}

