static void PatchRefreshListsV11(){bool previous=gRefreshing;gRefreshing=true;for(const auto& box:gPatchListBoxesV11){if(box.nativeIndex<0||box.nativeIndex>=(int)gControls.size())continue;auto& c=gControls[(size_t)box.nativeIndex];auto* state=PatchFindListStateV11(gPatchListStatesV11,box.binding);if(!state||!c.hwnd)continue;SendMessageW(c.hwnd,LB_SETSEL,FALSE,(LPARAM)-1);for(size_t index=0;index<c.options.size();++index){std::string option=PatchUtf8V11(c.options[index]);if(std::find(state->value.begin(),state->value.end(),option)!=state->value.end())SendMessageW(c.hwnd,LB_SETSEL,TRUE,(LPARAM)index);}}gRefreshing=previous;}
static void PatchReportListErrorV11(const std::string& message){gPatchListRuntimeErrorV11=true;gPatchListRuntimeErrorMessageV11=message;if(!gSmokeMode)MessageBoxW(nullptr,PatchWideV11(message).c_str(),L"Patch stopped",MB_OK|MB_ICONERROR);}
static bool PatchApplyListActionV11(const PatchListActionV11& action,const std::vector<std::string>* eventList){auto* state=PatchFindListStateV11(gPatchListStatesV11,action.target);if(!state)return false;for(const auto& op:action.ops){if(op.op==4){state->value.clear();continue;}if(op.op==1){if(op.valueKind==2){if(!eventList)return false;state->value=*eventList;}else if(op.valueKind==1)state->value=op.listValue;else return false;continue;}if(op.valueKind!=1)return false;if(op.op==2){state->value.push_back(op.textValue);continue;}if(op.op==3){auto it=std::find(state->value.begin(),state->value.end(),op.textValue);if(it==state->value.end()){PatchReportListErrorV11("Cannot remove "+op.textValue+" because it is not in the list.");return false;}state->value.erase(it);continue;}return false;}return true;}
static const PatchListActionV11* PatchListActionAtV11(const PatchListEventV11* meta,uint32_t index){if(!meta)return nullptr;for(const auto& action:meta->actions)if(action.actionIndex==index)return &action;return nullptr;}

