static void PatchDispatchResultV11(const std::wstring& id,uint8_t kind,const std::wstring& value=L""){for(const auto& event:gEvents)if(event.control==id&&event.kind==kind)PatchExecuteEventV11(event,false,value,nullptr);}
static void PatchExecuteEventV11(const Event& event,bool eventBool,const std::wstring& eventText,const std::vector<std::string>* eventList){const auto* meta=PatchFindListEventV11(gPatchListEventsV11,PatchUtf8V11(event.control),event.kind);for(uint32_t index=0;index<(uint32_t)event.actions.size();++index){if(const auto* listAction=PatchListActionAtV11(meta,index)){if(!PatchApplyListActionV11(*listAction,eventList)){if(!gPatchListRuntimeErrorV11)PatchReportListErrorV11("Invalid sealed list operation.");return;}continue;}const auto& action=event.actions[index];if(action.kind==ACT_OPEN)ShowWindow(gForms[gFormById[action.form]].hwnd,SW_SHOW);else if(action.kind==ACT_CLOSE)ShowWindow(gForms[gFormById[action.form]].hwnd,SW_HIDE);else if(action.kind==ACT_DIALOG)ShowInfoDialog(action);else if(action.kind==ACT_CONFIRM){bool accepted=ShowConfirmDialog(action);gLastResultSource=action.id;gLastResultValue.clear();gLastResultEvent=accepted?EV_CONFIRMED:EV_CANCELLED;PatchDispatchResultV11(action.id,accepted?EV_CONFIRMED:EV_CANCELLED);}else if(action.kind==ACT_OPEN_FILE||action.kind==ACT_SAVE_FILE){std::wstring value;bool chosen=ShowFileDialog(action,value);gLastResultSource=action.id;gLastResultValue=chosen?value:L"";gLastResultEvent=chosen?EV_CHOSEN:EV_CANCELLED;PatchDispatchResultV11(action.id,chosen?EV_CHOSEN:EV_CANCELLED,chosen?value:L"");}else if(action.kind==ACT_CHANGE){State& state=gStates[gStateByName[action.target]];for(const auto& op:action.ops)ApplyOperation(state,op,eventBool,eventText);}}PatchSyncListShadowsV11();RefreshUI();PatchRefreshListsV11();}

static void PatchDispatchControlV11(int index,uint8_t kind,HWND eventHwnd=nullptr){if(gRefreshing||index<0||index>=(int)gControls.size())return;auto& control=gControls[(size_t)index];if(control.id.empty())return;for(const auto& event:gEvents){if(event.control!=control.id||event.kind!=kind)continue;bool eventBool=false;std::wstring eventText;std::vector<std::string> eventList;const std::vector<std::string>* eventListPtr=nullptr;if(event.valueType==1&&control.kind==CK_CHECKBOX)eventBool=SendMessageW(control.hwnd,BM_GETCHECK,0,0)==BST_CHECKED;else if(event.valueType==2&&control.kind==CK_INPUT)eventText=WindowText(control.hwnd);else if(event.valueType==2&&control.kind==CK_COMBO)eventText=ComboText(control.hwnd);else if(event.valueType==2&&control.kind==CK_LISTBOX){const auto* box=PatchFindListBoxV11(gPatchListBoxesV11,PatchUtf8V11(control.id));if(box){eventList=PatchSelectedListValuesV11(*box);eventListPtr=&eventList;}else eventText=ListBoxText(control.hwnd);}else if(event.valueType==2&&control.kind==CK_RADIO)eventText=WindowText(eventHwnd?eventHwnd:control.hwnd);PatchExecuteEventV11(event,eventBool,eventText,eventListPtr);}}
