static bool PatchInstallTableV10(const PatchTableV10& table){auto& c=gControls[(size_t)table.nativeIndex];HWND parent=gForms[(size_t)c.formIndex].hwnd;int x=c.x,y=c.y;if(c.parentTabIndex>=0){if(c.parentTabIndex>=(int)gControls.size())return false;const auto& tab=gControls[(size_t)c.parentTabIndex];x=tab.x+10+c.x;y=tab.y+30+c.y;}if(c.hwnd)DestroyWindow(c.hwnd);c.hwnd=CreateWindowExW(WS_EX_CLIENTEDGE,WC_LISTVIEWW,L"",WS_CHILD|WS_VISIBLE|WS_TABSTOP|LVS_REPORT|LVS_SINGLESEL|LVS_SHOWSELALWAYS,x,y,c.width,c.height,parent,reinterpret_cast<HMENU>((INT_PTR)c.commandId),gInstance,nullptr);if(!c.hwnd)return false;if(gGuiFont)SendMessageW(c.hwnd,WM_SETFONT,(WPARAM)gGuiFont,TRUE);ListView_SetExtendedListViewStyle(c.hwnd,LVS_EX_FULLROWSELECT|LVS_EX_GRIDLINES|LVS_EX_DOUBLEBUFFER);const int columnWidth=table.columns.empty()?c.width:max(40,c.width/(int)table.columns.size());for(int columnIndex=0;columnIndex<(int)table.columns.size();++columnIndex){std::wstring title=PatchWideV11(table.columns[(size_t)columnIndex]);LVCOLUMNW column{};column.mask=LVCF_TEXT|LVCF_WIDTH|LVCF_SUBITEM;column.cx=columnIndex+1==(int)table.columns.size()?max(40,c.width-columnWidth*columnIndex):columnWidth;column.iSubItem=columnIndex;column.pszText=title.data();if(ListView_InsertColumn(c.hwnd,columnIndex,&column)<0)return false;}for(int rowIndex=0;rowIndex<(int)table.rows.size();++rowIndex){const auto& row=table.rows[(size_t)rowIndex];std::wstring first=PatchWideV11(row.empty()?std::string():row[0]);LVITEMW item{};item.mask=LVIF_TEXT;item.iItem=rowIndex;item.iSubItem=0;item.pszText=first.data();if(ListView_InsertItem(c.hwnd,&item)<0)return false;for(int columnIndex=1;columnIndex<(int)row.size();++columnIndex){std::wstring value=PatchWideV11(row[(size_t)columnIndex]);ListView_SetItemText(c.hwnd,rowIndex,columnIndex,value.data());}}c.kind=9;return true;}
